import * as T from './vendor/three.module.min.js';
import {campSurface98,campTexture98} from './camp-life-materials98.js';
export function createCampPropKit98(){
 const wood=campSurface98('weathered-boards',{roughness:.97,bumpScale:.021}),tin=campSurface98('rusty-tin',{roughness:.85,metalness:.30,bumpScale:.012,side:T.DoubleSide}),concrete=campSurface98('dirty-concrete',{roughness:.97,bumpScale:.013}),metal=new T.MeshStandardMaterial({color:0xb6b7ac,roughness:.49,metalness:.55}),black=new T.MeshStandardMaterial({color:0x252725,roughness:.9}),cream=new T.MeshStandardMaterial({color:0xd4cbb3,roughness:.47}),brass=new T.MeshStandardMaterial({color:0x9b854d,roughness:.57,metalness:.65}),white=new T.MeshLambertMaterial({color:0xcfc9b9,flatShading:true});
 let woodSerial=0;const cache=new Map();const mat=key=>{if(!cache.has(key))cache.set(key,campSurface98(key,{bumpScale:.002}));return cache.get(key);};
 function mesh(root,g,m,p=[0,0,0]){const o=new T.Mesh(g,m);o.position.fromArray(p);o.castShadow=o.receiveShadow=true;root.add(o);return o;}
 function mapSolid(g,w,h,d,m){const pos=g.attributes.position,uv=g.attributes.uv,n=g.attributes.normal;const dimensions=[w,h,d],long=dimensions.indexOf(Math.max(...dimensions)),offset=.067+(woodSerial++%10)*.082;for(let k=0;k<uv.count;k++){const v=[pos.getX(k),pos.getY(k),pos.getZ(k)],normal=[Math.abs(n.getX(k)),Math.abs(n.getY(k)),Math.abs(n.getZ(k))],face=normal.indexOf(Math.max(...normal)),uAxis=face===0?2:0,vAxis=face===1?2:1;if(m===wood){const cross=[0,1,2].find(a=>a!==long&&a!==face)??((long+1)%3);uv.setXY(k,offset+(v[cross]/dimensions[cross]+.5)*.050,.07+(v[long]/dimensions[long]+.5)*.86);}else if(m.name==='Generated V98 peas')uv.setXY(k,v[uAxis]/.18+.5,v[vAxis]/.18+.5);else uv.setXY(k,v[uAxis]/dimensions[uAxis]+.5,v[vAxis]/dimensions[vAxis]+.5);}return g;}
 function box(root,w,h,d,m,p=[0,0,0]){return mesh(root,mapSolid(new T.BoxGeometry(w,h,d),w,h,d,m),m,p);}
 function bevel(root,w,h,d,m,p=[0,0,0],r=.008){const s=new T.Shape(),x=-w/2,y=-h/2;s.moveTo(x+r,y);s.lineTo(x+w-r,y);s.lineTo(x+w,y+r);s.lineTo(x+w,y+h-r);s.lineTo(x+w-r,y+h);s.lineTo(x+r,y+h);s.lineTo(x,y+h-r);s.lineTo(x,y+r);s.closePath();const g=new T.ExtrudeGeometry(s,{depth:d-2*r,bevelEnabled:true,bevelSize:r,bevelThickness:r,bevelSegments:1,steps:1,curveSegments:1});g.translate(0,0,-d/2+r);return mesh(root,mapSolid(g,w,h,d,m),m,p);}
 function cyl(root,r,h,m,p=[0,0,0],n=10,r2=r,open=false){return mesh(root,new T.CylinderGeometry(r,r2,h,n,1,open),m,p);}
 function rod(root,a,b,r,m,n=6){const av=new T.Vector3(...a),d=new T.Vector3(...b).sub(av),o=cyl(root,r,d.length(),m,av.addScaledVector(d,.5).toArray(),n);o.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),d.normalize());return o;}
 function lathe(root,rows,m,n=12,p=[0,0,0]){return mesh(root,new T.LatheGeometry(rows.map(v=>new T.Vector2(...v)),n),m,p);}
 function cable(root,points,r=.008,m=black){return mesh(root,new T.TubeGeometry(new T.CatmullRomCurve3(points.map(p=>new T.Vector3(...p))),18,r,4,false),m);}
 function face(root,w,h,key,p,rotation=null){const o=mesh(root,new T.PlaneGeometry(w,h),mat(key),p);if(rotation)o.rotation.set(...rotation);return o;}
 function cigarette(root,p=[0,0,0],lit=false){const g=new T.Group();root.add(g);g.position.fromArray(p);cyl(g,.0038,.064,white,[0,.027,0],5);cyl(g,.004,.023,new T.MeshLambertMaterial({color:0xaa7449}),[0,-.015,0],5);if(lit)cyl(g,.0043,.004,new T.MeshBasicMaterial({color:0xc14a18}),[0,.061,0],5);return g;}
 function ashtray(root,p,scalloped=true){const g=new T.Group();root.add(g);g.position.fromArray(p);g.name='Deep ceramic ashtray / ash, notches and spent cigarettes';lathe(g,[[0,0],[.057,0],[.082,.020],[.079,.031],[.061,.024],[.051,.009],[0,.009]],cream,scalloped?12:8);for(let j=0;j<(scalloped?6:4);j++){const a=j*Math.PI*2/(scalloped?6:4);const l=box(g,.014,.006,.025,black,[Math.sin(a)*.07,.026,Math.cos(a)*.07]);l.rotation.y=a;}for(let j=0;j<10;j++){const a=j*2.39,r=.034*Math.sqrt(j/10);const q=mesh(g,new T.DodecahedronGeometry(.006+(j%3)*.002,0),black,[Math.sin(a)*r,.013,Math.cos(a)*r]);q.scale.y=.22;}for(let j=0;j<2;j++){const c=cigarette(g,[j*.025-.019,.021,j*.015-.014],j===0);c.rotation.set(.3,0,1.25+j*.8);c.scale.y=.58;}return g;}
 function pack(root,p,key,ry=0){const g=new T.Group();root.add(g);g.position.fromArray(p);g.rotation.y=ry;bevel(g,.055,.022,.085,cream,[0,.011,0],.002);face(g,.051,.081,key,[0,.0245,0],[-Math.PI/2,0,0]);box(g,.051,.0015,.011,white,[0,.024,-.033]);return g;}
 function can(root,p,key,tall=false){const g=new T.Group();g.name='Opened '+key+' can / rolled rims and pull tab';g.position.fromArray(p);root.add(g);const r=.034,h=tall?.169:.123;lathe(g,[[0,0],[r*.86,0],[r,.008],[r,h-.013],[r*.86,h-.003],[r*.86,h],[0,h]],metal,12);cyl(g,r+.0004,h-.026,mat(key),[0,h*.49,0],12,r+.0004,true);const hole=mesh(g,new T.CircleGeometry(.009,8),black,[0,h+.0005,.009]);hole.rotation.x=-Math.PI/2;hole.scale.y=1.5;const tab=mesh(g,new T.TorusGeometry(.008,.0025,3,8),metal,[0,h+.002,-.007]);tab.rotation.x=Math.PI/2;for(const yy of [.006,h])lathe(g,[[r*.83,yy],[r*.90,yy-.003],[r*.92,yy],[r*.86,yy+.002]],metal,12);return g;}
 function radio(root,p){const g=new T.Group();g.name='Twin-speaker cassette boombox / reference 3';root.add(g);g.position.fromArray(p);bevel(g,.56,.267,.145,metal,[0,.134,0],.012);box(g,.539,.025,.15,wood,[0,.278,0]);face(g,.542,.251,'radio-front',[0,.141,.074]);for(const x of [-.185,.185]){const rim=mesh(g,new T.TorusGeometry(.085,.003,4,24),black,[x,.128,.075]);cyl(g,.016,.012,black,[x,.233,.081],10).rotation.x=Math.PI/2;}bevel(g,.125,.093,.009,black,[0,.133,.079],.003);const cassette=face(g,.115,.083,'radio-front',[0,.133,.084]);const cassetteUV=cassette.geometry.attributes.uv;for(let k=0;k<cassetteUV.count;k++)cassetteUV.setXY(k,.39+cassetteUV.getX(k)*.22,.30+cassetteUV.getY(k)*.36); // Cassette window has real recessed glazing over the artwork.
 for(let k=0;k<6;k++)box(g,.017,.008,.026,cream,[-.06+k*.024,.299,.025]);for(const x of [-.22,.22]){box(g,.019,.088,.019,black,[x,.318,-.015]);box(g,.027,.01,.036,metal,[x,.28,-.015]);}bevel(g,.46,.024,.024,black,[0,.365,-.015],.004);rod(g,[-.247,.28,-.048],[-.36,.70,-.048],.0035,metal,6);for(let n=0;n<9;n++)box(g,.022,.002,.061,black,[.155+n*.008,.292,-.028]);return g;}
 function table(root,p){const g=new T.Group();g.name='Weathered lakeshore table / exact reference inventory';root.add(g);g.position.fromArray(p);g.userData.legs=[];for(let n=0;n<6;n++)box(g,1.12,.043,.15,wood,[Math.sin(n*3)*.005,.754,-.4+n*.16]);for(const x of [-.44,.44])for(const z of [-.32,.32]){const leg=box(g,.07,.738,.075,wood,[x,.369,z]);leg.rotation.z=0;g.userData.legs.push(leg);}for(const x of [-.44,.44])box(g,.044,.084,.74,wood,[x,.64,0]);box(g,.94,.08,.04,wood,[0,.27,.23]);radio(g,[-.025,.776,-.225]);can(g,[-.367,.776,.105],'can-vanilla');can(g,[.345,.776,-.29],'can-budlight',true);can(g,[.40,.776,-.07],'can-budlight',true);pack(g,[-.15,.776,.255],'cigarettes-turquoise',-.12);ashtray(g,[.19,.776,.25],true);const lighter=new T.Group();g.add(lighter);lighter.position.set(.32,.776,.093);bevel(lighter,.039,.054,.014,brass,[0,.028,0],.003);bevel(lighter,.04,.028,.016,brass,[-.012,.072,0],.003).rotation.z=-.52;box(lighter,.025,.008,.013,metal,[0,.060,0]);return g;}
 function cooler(root,p){const g=new T.Group();root.add(g);g.position.fromArray(p);g.name='Red insulated cooler / white lid, hinge and open lining';const red=mat('cooler-panel');bevel(g,.64,.44,.43,red,[0,.23,0],.024);box(g,.59,.024,.37,cream,[0,.455,0]);box(g,.49,.002,.29,black,[0,.468,0]);for(const s of [-1,1]){box(g,.037,.055,.40,cream,[s*.302,.46,0]);rod(g,[s*.335,.23,-.09],[s*.335,.32,-.09],.013,cream);rod(g,[s*.335,.23,.09],[s*.335,.23,-.09],.013,cream);rod(g,[s*.335,.23,.09],[s*.335,.32,.09],.013,cream);}const lid=new T.Group();lid.position.set(0,.49,-.21);lid.rotation.x=-1.06;g.add(lid);bevel(lid,.65,.056,.45,cream,[0,.01,.214],.014);box(lid,.55,.004,.33,white,[0,-.022,.214]);box(g,.24,.013,.24,cream,[.15,.477,.005]);can(g,[.16,.485,.014],'can-budlight',true);return g;}
 function officeSet(root){const g=new T.Group();g.name='Reference 4 / Modelo pair, cigarette pack, ashtray';root.add(g);g.position.set(-1.7,.795,-2.35);can(g,[-.29,0,-.075],'can-modelo');can(g,[-.06,0,-.015],'can-modelo');ashtray(g,[-.24,0,-.32],false);pack(g,[.12,0,-.29],'cigarettes-red',.29);const c=cigarette(g,[.31,.005,-.34]);c.rotation.set(0,.6,Math.PI/2);return g;}
 return{wood,tin,concrete,metal,black,cream,brass,white,mat,mesh,box,bevel,cyl,rod,lathe,cable,face,cigarette,ashtray,can,table,cooler,officeSet};
}
